"""PlantSeg diseases, part A: blueberry, raspberry, soybean (no PlantVillage diseases) and banana to celery. See plantseg_existing.py."""
from plantseg_dsl import D, S, M, L

PLANTS = {}


def remove_step(what, why="Fewer spores are left to spread.", mode="TapRegion", days=2):
    return S(f"Remove {what}", f"Pick off {what} when the plants are dry and take them away.", why, mode, days, "Remove")


def spray_step(what="a registered fungicide", why="Protects healthy growth; it cannot cure what is already infected.", days=3):
    return S("Protective spray", f"Spray {what} on the label's schedule.", why, "SprayApply", days, "Protect", True)


